//! Native Full input validation plus read-only funded-original diagnosis.
//! Fixture provenance is generated by the core production preparation test.
use super::*;
use kaspa_consensus_core::{
    hashing::{sighash::{Mldsa87SigHashReusedValuesUnsync, calc_mldsa87_signature_hash}, sighash_type::SIG_HASH_ALL},
    mass::MassCalculator,
    palw_court_original_escrow_v1::{FundingConsentV1, FundingTermsV1, COURT_ORIGINAL_FUNDING_SIGNATURE_CONTEXT_V1},
    palw_state_v2::{PalwFundedOriginalCandidateV1, PalwStateCarriageV2, PalwStateParamsV2},
    palw_tir_funded_original_envelope_v1::PalwTirFundedOriginalEnvelopeV1,
    palw_tir_public_fp_envelope_v1::PalwTirPublicFpEnvelopeV1,
    tx::{PopulatedTransaction, TransactionInput, TransactionOutput, UtxoEntry},
    utxo::utxo_collection::UtxoCollection,
};
use kaspa_txscript::{MLDSA87_TX_CONTEXT, script_builder::ScriptBuilder};
use libcrux_ml_dsa::ml_dsa_87 as mldsa;

#[tokio::test]
async fn palw_funded_original_real_native_inputs_preserve_fallback_and_refuse_incomplete_admission() {
    let dir = std::env::var("MISAKA_G14_NATIVE_FIXTURE_DIR").unwrap_or_else(|_| {
        std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/g14-funded-original-native")
            .to_string_lossy().into_owned()
    });
    let read = |name: &str| std::fs::read(std::path::Path::new(&dir).join(name)).unwrap();
    let params: PalwStateParamsV2 = borsh::from_slice(&read("params.borsh")).unwrap();
    let carriage: PalwStateCarriageV2 = borsh::from_slice(&read("state.borsh")).unwrap();
    let state = carriage.into_state(&params, None).unwrap();
    let root = state.state_root();
    let original = PalwTirPublicFpEnvelopeV1::decode_v1(&read("original.tfp1")).unwrap();
    let fp = original.original_fp_v1().unwrap();
    let now: u64 = std::str::from_utf8(&read("accepting-daa.txt")).unwrap().parse().unwrap();
    // Existing native TEST bundle, not a new tariff/production preset. The
    // standalone original state remains the core-generated preparation fixture.
    let catalog=palw_v2_test_catalog();
    let bundle=palw_v2_test_bundle_funded_for(&catalog,64);
    let config=ConfigBuilder::new(MAINNET_PARAMS).skip_proof_of_work()
        .edit_consensus_params(move |p| {
            p.palw_consensus_mode=kaspa_consensus_core::palw_mode_v2::PalwConsensusMode::ConsensusV2(bundle.clone());
            *p=p.clone().with_palw_v2_cadence();
        }).build();
    let ctx = TestContext::new(TestConsensus::new(&config));
    let vp = ctx.consensus.virtual_processor();
    let seed = [0x73; 32]; // Public local fixture only.
    let kp = mldsa::generate_key_pair(seed);
    let key = kp.verification_key.as_ref().to_vec();
    let payer = kaspa_consensus_core::mldsa87_primitives::mldsa87_key_id(&key);
    let address = kaspa_hashes::blake2b_512_address_payload(&key);
    assert_ne!(payer,address,"key identity and native address use distinct hash domains");
    let spk = kaspa_consensus_core::mldsa87_primitives::p2pkh_mldsa87_spk(&address.as_bytes());
    let h = |n| kaspa_hashes::Hash64::from_u64_word(n);
    let mut consent = FundingConsentV1 { terms: FundingTermsV1 {
        version:1, network_domain:vp.palw_network_domain_v2(), claim:fp.claim_id(),
        job_identity: original.pledge.job_identity, execution_root:fp.commitment.execution_root,
        source_id:original.pledge.source_id, relative_graph_id:h(2), fee_profile_id:h(3), capital_profile_id:h(4),
        retention_profile_id:h(5), settlement_policy_id:h(6), accept_from_daa:now, accept_until_daa:now+100,
        material_until_daa:now+20_000, funding_output_index:0, funding_amount_sompi:1_000_000_000,
        payer_key_id:payer, refund_payload:address, nonce:h(7),
    }, signature:vec![] };
    consent.signature = mldsa::sign(&kp.signing_key, consent.terms.id_v1().as_byte_slice(),
        COURT_ORIGINAL_FUNDING_SIGNATURE_CONTEXT_V1, seed).unwrap().as_ref().to_vec();
    let envelope = PalwTirFundedOriginalEnvelopeV1::new_v1(original.encode_v1().unwrap(),consent,key.clone()).unwrap();
    let previous = TransactionOutpoint::new(h(0xF135),0);
    let value = 2_000_000_000;
    let entry = UtxoEntry::new(value,spk.clone(),0,false);
    let sign = |tx: &mut Transaction, previous_entry: &UtxoEntry| {
        let mass = MassCalculator::new(0,0,0,config.params.storage_mass_parameter)
            .calc_contextual_masses(&PopulatedTransaction::new(tx,vec![previous_entry.clone()])).unwrap().storage_mass;
        tx.set_mass(mass);
        let hash = calc_mldsa87_signature_hash(&PopulatedTransaction::new(tx,vec![previous_entry.clone()]),0,SIG_HASH_ALL,
            &Mldsa87SigHashReusedValuesUnsync::new());
        let mut item = mldsa::sign(&kp.signing_key,hash.as_bytes().as_slice(),MLDSA87_TX_CONTEXT,seed).unwrap().as_ref().to_vec();
        item.push(SIG_HASH_ALL.to_u8());
        tx.inputs[0].signature_script = ScriptBuilder::new().add_data(&item).unwrap().add_data(&key).unwrap().drain();
        tx.finalize();
    };
    let make = |payload: Vec<u8>| {
        let mut tx=Transaction::new(crate::constants::TX_VERSION,vec![TransactionInput::new(previous,vec![],0,1)],
            vec![TransactionOutput::new(envelope.funding.terms.funding_amount_sompi,spk.clone())],0,
            kaspa_consensus_core::subnets::SUBNETWORK_ID_PALW_FP_COMMITMENT,0,payload);
        sign(&mut tx,&entry);tx
    };
    let view:UtxoCollection=[(previous,entry.clone())].into_iter().collect();
    let full=crate::processes::transaction_validator::tx_validation_in_utxo_context::TxValidationFlags::Full;
    let tx=make(envelope.encode_v1().unwrap());
    let validated=vp.validate_transaction_in_utxo_context(&tx,&view,now,full,None).unwrap();
    let diagnostic=vp.palw_funded_original_candidate_from_native_v1(&state,now,&validated);
    assert!(matches!(&diagnostic,PalwFundedOriginalCandidateV1::Missing(s) if s.starts_with("native source checked;")),"{diagnostic:?}");
    assert_eq!(state.state_root(),root);
    assert!(state.claim(&fp.claim_id()).is_none());
    assert_eq!(validated.calculated_fee,value-envelope.funding.terms.funding_amount_sompi);
    // Full native inputs and payer consent stay valid. Corrupt ONLY the
    // producer's separate source pledge signature, keeping its signed scope,
    // original FP commitment, funding profile IDs/output/amount unchanged.
    let mut bad_source_envelope=envelope.clone();
    let mut bad_source_original=bad_source_envelope.original_v1().unwrap();
    bad_source_original.pledge.signature[0]^=1;
    bad_source_envelope.original_envelope=bad_source_original.encode_v1().unwrap();
    bad_source_envelope.funding.verify_signature_v1(&bad_source_envelope.payer_pubkey).unwrap();
    bad_source_envelope.original_v1().unwrap().original_fp_v1().unwrap()
        .validate_signature_v3(kaspa_consensus_core::palw_constraint_stream_carriage_v1::palw_staged_verify_mldsa87_v1).unwrap();
    let bad_source=make(bad_source_envelope.encode_v1().unwrap());
    let bad_source_validated=vp.validate_transaction_in_utxo_context(&bad_source,&view,now,full,None).unwrap();
    assert_eq!(bad_source_validated.calculated_fee,validated.calculated_fee);
    assert_eq!(vp.palw_funded_original_candidate_from_native_v1(&state,now,&bad_source_validated),
        PalwFundedOriginalCandidateV1::Invalid("current producer source pledge signature"));
    assert_eq!(bad_source.outputs,tx.outputs);
    assert_eq!(state.state_root(),root);
    assert!(state.claim(&fp.claim_id()).is_none());
    // Unknown profiles in the signed consent never create funded standing.
    // The ordinary own output remains spendable with the actual payer signature.
    let fallback=TransactionOutpoint::new(tx.id(),0);
    let fallback_entry=UtxoEntry::new(tx.outputs[0].value,tx.outputs[0].script_public_key.clone(),now,false);
    let mut spend=Transaction::new(crate::constants::TX_VERSION,vec![TransactionInput::new(fallback,vec![],0,1)],
        vec![TransactionOutput::new(tx.outputs[0].value-1,spk.clone())],0,kaspa_consensus_core::subnets::SUBNETWORK_ID_NATIVE,0,vec![]);
    sign(&mut spend,&fallback_entry);
    let fallback_view:UtxoCollection=[(fallback,fallback_entry)].into_iter().collect();
    vp.validate_transaction_in_utxo_context(&spend,&fallback_view,now+1,full,None).unwrap();
    // An ordinary valid carrier may pay a trap script, but it must NEVER be
    // recognized as a payer-recoverable funded-original fallback.
    let mut trap = tx.clone();
    trap.outputs[0].script_public_key = kaspa_consensus_core::mldsa87_primitives::p2pkh_mldsa87_spk(&payer.as_bytes());
    sign(&mut trap,&entry);
    assert!(trap.id_is_current(), "trap must reach output authentication, not stale-id refusal");
    envelope.funding.verify_signature_v1(&envelope.payer_pubkey).unwrap();
    let actual_trap = kaspa_consensus_core::palw_court_original_escrow_v1::inspect_transaction_v1(&trap,0).unwrap();
    assert_eq!(envelope.funding.check_actual_output_v1(&actual_trap,&envelope.payer_pubkey),
        Err(kaspa_consensus_core::palw_court_original_escrow_v1::FundingRefusalV1::OutputMismatch));
    let trap_validated=vp.validate_transaction_in_utxo_context(&trap,&view,now,full,None).unwrap();
    assert_eq!(vp.palw_funded_original_candidate_from_native_v1(&state,now,&trap_validated),
        PalwFundedOriginalCandidateV1::Invalid("actual funding output or payer consent signature"));
    assert_eq!(state.state_root(),root);
    let mut bad=tx.clone();bad.inputs[0].signature_script[10]^=1;
    assert!(vp.validate_transaction_in_utxo_context(&bad,&view,now,full,None).is_err());
    assert!(vp.validate_transaction_in_utxo_context(&tx,&UtxoCollection::default(),now,full,None).is_err());
    assert!(matches!(vp.palw_funded_original_candidate_from_native_v1(&state,now+101,&validated),PalwFundedOriginalCandidateV1::Invalid(_)));
    let mut replaced = PalwStateCarriageV2::from_state(&state);
    let replaced_bond = replaced.bonds.get_mut(&kaspa_consensus_core::palw_state_v2::PalwBondKeyV2(fp.commitment.job.executor_bond)).unwrap();
    replaced_bond.pubkey = key.clone();
    replaced_bond.operator_id = kaspa_consensus_core::palw_state_v2::palw_operator_id_v2(&key);
    let replaced = replaced.into_state(&params,None).unwrap();
    assert!(matches!(vp.palw_funded_original_candidate_from_native_v1(&replaced,now,&validated),PalwFundedOriginalCandidateV1::Invalid(_)));
    // The original was generated and prepared with this public TEST producer
    // key. Mutations below remain real MLDSA signed carrier transactions.
    let producer_seed=[0x6D;32];
    let producer_key=mldsa::generate_key_pair(producer_seed);
    assert_eq!(producer_key.verification_key.as_ref(),fp.commitment.job.executor_pubkey.as_slice());
    let mutate_pledge=|source:Option<kaspa_consensus_core::Hash64>,expiry:Option<u64>| {
        let mut candidate=envelope.clone();
        let mut original=candidate.original_v1().unwrap();
        if let Some(source)=source {original.pledge.source_id=source;candidate.funding.terms.source_id=source;}
        if let Some(expiry)=expiry {original.pledge.accept_until_daa=expiry;}
        original.pledge.signature=mldsa::sign(&producer_key.signing_key,original.pledge.id_v1().as_byte_slice(),
            kaspa_consensus_core::palw_tir_public_custody_v1::PALW_TIR_SOURCE_PLEDGE_CONTEXT_V1,producer_seed).unwrap().as_ref().to_vec();
        candidate.original_envelope=original.encode_v1().unwrap();
        candidate.funding.signature=mldsa::sign(&kp.signing_key,candidate.funding.terms.id_v1().as_byte_slice(),
            COURT_ORIGINAL_FUNDING_SIGNATURE_CONTEXT_V1,seed).unwrap().as_ref().to_vec();
        make(candidate.encode_v1().unwrap())
    };
    assert!(now>1,"fixture must span a real registration/acceptance boundary");
    for (candidate,reason) in [
        (mutate_pledge(Some(h(0xF136)),None),"producer pledge differs from actual native source"),
        (mutate_pledge(None,Some(now-1)),"producer source pledge acceptance clock"),
    ] {
        let actual=vp.validate_transaction_in_utxo_context(&candidate,&view,now,full,None).unwrap();
        assert_eq!(vp.palw_funded_original_candidate_from_native_v1(&state,now,&actual),PalwFundedOriginalCandidateV1::Invalid(reason));
        assert_eq!(candidate.outputs,tx.outputs);assert_eq!(actual.calculated_fee,validated.calculated_fee);
        assert_eq!(state.state_root(),root);
    }
    // Real current state metadata is authoritative, not the signed profile IDs.
    let mut future=PalwStateCarriageV2::from_state(&state);
    future.classes.get_mut(&fp.commitment.job.class_id).unwrap().registered_daa=now+1;
    let future=future.into_state(&params,None).unwrap();
    assert_eq!(vp.palw_funded_original_candidate_from_native_v1(&future,now,&validated),
        PalwFundedOriginalCandidateV1::Invalid("native registered class time or artifact"));
    let mut foreign=PalwStateCarriageV2::from_state(&state);
    foreign.classes.get_mut(&fp.commitment.job.class_id).unwrap().artifact_root=h(0xF137);
    let foreign=foreign.into_state(&params,None).unwrap();
    assert_eq!(vp.palw_funded_original_candidate_from_native_v1(&foreign,now,&validated),
        PalwFundedOriginalCandidateV1::Invalid("native registered class time or artifact"));
    let mut geometry=PalwStateCarriageV2::from_state(&state);
    let layout_key=kaspa_consensus_core::palw_staged_court_state_v1::PalwStagedCourtKeyV1::TirLayout(fp.commitment.job.class_id);
    if let kaspa_consensus_core::palw_staged_court_state_v1::PalwStagedCourtRowV1::TirLayout(layout)=geometry.staged_courts.get_mut(&layout_key).unwrap() {
        assert!(!layout.commit_tiles.is_empty());
        layout.commit_tiles[0]=if layout.commit_tiles[0]==4 {8} else {4};
    } else {panic!("actual registered layout fixture");}
    let geometry=geometry.into_state(&params,None).unwrap();
    assert_eq!(vp.palw_funded_original_candidate_from_native_v1(&geometry,now,&validated),
        PalwFundedOriginalCandidateV1::Invalid("native original source geometry or job roots"));
    // Explicit local TEST configuration mutation only; no preset/fence is armed
    // in production. Resolve demand at registered DAA, NOT accepting DAA.
    let mut demand_config=config.params.clone();
    demand_config.palw_tir_v1=Some(kaspa_consensus_core::palw_tir_v1::PalwTirFenceV1::testnet12_v1(
        kaspa_consensus_core::config::params::ForkActivation::new(0)));
    demand_config.sync_palw_tir_v1();
    demand_config.palw_tir_fence2=Some(kaspa_consensus_core::config::params::ForkActivation::new(1));
    demand_config.sync_palw_tir_fence2();
    let demand_config=ConfigBuilder::new(demand_config).skip_proof_of_work().build();
    let demand_ctx=TestContext::new(TestConsensus::new(&demand_config));
    let demand_vp=demand_ctx.consensus.virtual_processor();
    assert_eq!(demand_vp.palw_network_domain_v2(),vp.palw_network_domain_v2());
    let actual=demand_vp.validate_transaction_in_utxo_context(&tx,&view,now,full,None).unwrap();
    let mut old=PalwStateCarriageV2::from_state(&state);
    old.classes.get_mut(&fp.commitment.job.class_id).unwrap().registered_daa=0;
    let old=old.into_state(&params,None).unwrap();
    assert!(matches!(demand_vp.palw_funded_original_candidate_from_native_v1(&old,now,&actual),
        PalwFundedOriginalCandidateV1::Missing(s) if s.contains("registered Release2000 demand")));
    let mut newer=PalwStateCarriageV2::from_state(&state);
    newer.classes.get_mut(&fp.commitment.job.class_id).unwrap().registered_daa=1;
    let newer=newer.into_state(&params,None).unwrap();
    assert!(matches!(demand_vp.palw_funded_original_candidate_from_native_v1(&newer,now,&actual),
        PalwFundedOriginalCandidateV1::Missing(s) if s.contains("registered H7 demand")));
    // The actual configured court/ladder is used by native source construction.
    // A smaller TEST court cannot be replaced by a producer's signed hash.
    assert_eq!(state.class_step_ladder_v1(&fp.commitment.job.class_id,2),2,"fixture has no held uplift");
    let mut small_config=config.params.clone();
    if let kaspa_consensus_core::palw_mode_v2::PalwConsensusMode::ConsensusV2(bundle)=&mut small_config.palw_consensus_mode {
        bundle.court=kaspa_consensus_core::palw_mode_v2::PalwCourtParamsV2::new(2,1,2).unwrap();
    } else {panic!("native fixture consensus-v2 policy");}
    let small_config=ConfigBuilder::new(small_config).skip_proof_of_work().build();
    let small_ctx=TestContext::new(TestConsensus::new(&small_config));
    let small_vp=small_ctx.consensus.virtual_processor();
    let actual=small_vp.validate_transaction_in_utxo_context(&tx,&view,now,full,None).unwrap();
    assert_eq!(small_vp.palw_funded_original_candidate_from_native_v1(&state,now,&actual),
        PalwFundedOriginalCandidateV1::Invalid("native original source geometry or job roots"));
    assert_eq!(tx.outputs.len(),1);assert_eq!(state.state_root(),root);assert!(state.claim(&fp.claim_id()).is_none());
    for payload in [b"TFO1".to_vec(), {
        let mut bad=envelope.clone();bad.funding.signature[0]^=1;bad.encode_v1().unwrap()
    }] {
        let bad=make(payload);
        let accepted=vp.validate_transaction_in_utxo_context(&bad,&view,now,full,None).unwrap();
        assert!(matches!(vp.palw_funded_original_candidate_from_native_v1(&state,now,&accepted),PalwFundedOriginalCandidateV1::Invalid(_)));
        assert_eq!(state.state_root(),root);
    }
}
